using VisionCore;
namespace VisionFramework;
// Source-guided port of CPreproMaskTool scan conversion. UI hit testing remains continuous.
// Single precision, C# truncation and target-row advancement are observable SDK behavior.
public static class RoiRasterizer {
 public static byte[] CreateMask(IReadOnlyList<RoiDocument> regions,int width,int height,CancellationToken token=default){if(width<=0||height<=0)throw new ArgumentOutOfRangeException();var output=new byte[checked(width*height)];bool valid=false;var pixelRegions=regions.Select(r=>RoiGeometry.ToPixels(r,width,height)).ToArray();if(!pixelRegions.Any(r=>!r.Exclusion)||pixelRegions.Any(r=>!r.Exclusion&&r.Kind==RoiKind.FullImage))Array.Fill(output,(byte)255);foreach(var r in pixelRegions.Where(r=>!r.Exclusion&&r.Kind!=RoiKind.FullImage))Draw(r,output,width,height,255,token,ref valid);foreach(var r in pixelRegions.Where(r=>r.Exclusion))Draw(r,output,width,height,0,token,ref valid);if(pixelRegions.Any(r=>r.Kind!=RoiKind.FullImage)&&!valid)throw new InvalidDataException("ROI超出图像有效范围。");return output;}
 static void Span(byte[] image,int width,int height,int y,int from,int to,byte value,ref bool valid){if((uint)y>=(uint)height)return;from=Math.Clamp(from,0,width);to=Math.Clamp(to,0,width);if(to>=from)valid=true;if(to>from)Array.Fill(image,value,y*width+from,to-from);}
 static void Draw(RoiDocument r,byte[] image,int width,int height,byte value,CancellationToken token,ref bool valid){RoiValidator.Validate(r);switch(r.Kind){case RoiKind.Rectangle:case RoiKind.UprightRectangle:case RoiKind.LineBox:case RoiKind.SequentialBox:
   if(Math.Abs((float)r.AngleDegrees)<.0001f){float x=(float)r.CenterX,y=(float)r.CenterY,w=(float)r.Width,h=(float)r.Height;if(x-w/2>width||y-h/2>height||x+w/2<0||y+h/2<0)return;int left=(int)Math.Floor(Math.Max(0,x-w*.5f+.5f)),right=(int)Math.Floor(Math.Min(width,x+w*.5f+.5f)),top=(int)Math.Floor(Math.Max(0,y-h*.5f+.5f)),bottom=(int)Math.Floor(Math.Min(height,y+h*.5f+.5f));for(int row=top;row<bottom;row++){token.ThrowIfCancellationRequested();Span(image,width,height,row,left,right,value,ref valid);}}else{var points=new[]{new Point2(-r.Width/2,-r.Height/2),new Point2(r.Width/2,-r.Height/2),new Point2(r.Width/2,r.Height/2),new Point2(-r.Width/2,r.Height/2)}.Select(p=>RoiGeometry.World(r,p.X,p.Y)).ToArray();Polygon(points,image,width,height,value,token,ref valid);}break;
  case RoiKind.Polygon:Polygon(r.Vertices??[],image,width,height,value,token,ref valid);break;
  case RoiKind.Annulus:case RoiKind.SectorRing:case RoiKind.Sector:Sector(r,image,width,height,value,token,ref valid);break;
  case RoiKind.Circle:Circle(r,image,width,height,value,token,ref valid);break;
  default:throw new NotSupportedException("此类型没有已验证的SDK面积栅格实现："+r.Kind);
 }}
 static void Polygon(IReadOnlyList<Point2> points,byte[] image,int width,int height,byte value,CancellationToken token,ref bool valid){var p=points.Select(p=>((float)p.X/width,(float)p.Y/height)).ToArray();if(p.Length<3)return;float minY=1,maxY=0,minX=1,maxX=0;foreach(var q in p){minY=Math.Min(minY,q.Item2);maxY=Math.Max(maxY,q.Item2);minX=Math.Min(minX,q.Item1);maxX=Math.Max(maxX,q.Item1);}int top=Math.Max(0,(int)(minY*height+.5f)),bottom=Math.Min(height,(int)(maxY*height+.5f)),left=Math.Max(0,(int)(minX*width+.5f)),right=Math.Min(width,(int)(maxX*width+.5f));if(left>width||top>height)return;for(int y=top;y<bottom;y++){token.ThrowIfCancellationRequested();var hits=new List<int>();for(int i=0,j=p.Length-1;i<p.Length;j=i++){var a=p[i];var b=p[j];if(a.Item2*height<y&&b.Item2*height>=y||b.Item2*height<y&&a.Item2*height>=y)hits.Add((int)(a.Item1*width+(y-a.Item2*height)/((b.Item2-a.Item2)*height)*((b.Item1-a.Item1)*width)+.5f));}hits.Sort();for(int i=0;i+1<hits.Count&&hits[i]<right;i+=2)if(hits[i+1]>left)Span(image,width,height,y,Math.Max(left,hits[i]),Math.Min(right,hits[i+1]),value,ref valid);}}
 static void Circle(RoiDocument r,byte[] image,int width,int height,byte value,CancellationToken token,ref bool valid){float cx=(float)r.CenterX,cy=(float)r.CenterY,radius=(float)r.Radius,squared=radius*radius;int top=Math.Max(0,(int)(cy-radius+.5f)),bottom=Math.Min(height,(int)(cy+radius+.5f)),left=Math.Max(0,(int)(cx-radius+.5f)),right=Math.Min(width,(int)(cx+radius+.5f)),destination=top;for(int row=top;row<bottom;row++){token.ThrowIfCancellationRequested();if(radius<=Math.Abs(cy-row))continue;float dx=(float)Math.Sqrt(squared-(cy-row)*(cy-row));int a=Math.Max(left,(int)(cx-dx+.5f)),b=Math.Min(right,(int)(cx+dx+.5f));if(b>=a){Span(image,width,height,destination,a,b,value,ref valid);destination++;}}}
 static bool Angle(float x,float y,float start,float sweep){if(Math.Abs(sweep-360)<.0001f)return true;float angle=(float)(Math.Atan2(y,x)/Math.PI*180.0),end=start+sweep;if(end>180)end-=360;return start<end&&angle>=start&&angle<=end||start>=end&&(angle>=start||angle<=end);}
 static (float X,float Y) Point(float cx,float cy,float radius,double radians,bool bounding=false)=>bounding?(cx+radius*(float)Math.Cos(radians),cy+radius*(float)Math.Sin(radians)):((float)((double)cx+radius*Math.Cos(radians)),(float)((double)cy+radius*Math.Sin(radians)));
 static (float Left,float Top,float Right,float Bottom) Bounds(float cx,float cy,float inner,float outer,float start,float sweep){float a=start<0?start+360:start,end=a+sweep;var points=new[]{Point(cx,cy,inner,a/180.0*Math.PI,true),Point(cx,cy,outer,a/180.0*Math.PI,true),Point(cx,cy,inner,end/180.0*Math.PI,true),Point(cx,cy,outer,end/180.0*Math.PI,true)};float left=points.Min(p=>p.X),right=points.Max(p=>p.X),top=points.Min(p=>p.Y),bottom=points.Max(p=>p.Y);int first=(int)a/90;if(a%90>.0001f)first++;int last=(int)end/90;var cardinal=new[]{(cx+outer,cy),(cx,cy+outer),(cx-outer,cy),(cx,cy-outer)};for(int i=first;i<=last;i++){var p=cardinal[i%4];left=Math.Min(left,p.Item1);right=Math.Max(right,p.Item1);top=Math.Min(top,p.Item2);bottom=Math.Max(bottom,p.Item2);}return(left,top,left+(right-left),top+(bottom-top));}
 static void Sector(RoiDocument r,byte[] image,int width,int height,byte value,CancellationToken token,ref bool valid){float cx=(float)r.CenterX,cy=(float)r.CenterY,outer=(float)r.Radius,inner=(float)r.InnerRadius;var s=RoiGeometry.Parameters(r);float start=r.Kind is RoiKind.Annulus or RoiKind.SectorRing?0:(float)s.StartAngle,sweep=r.Kind is RoiKind.Annulus or RoiKind.SectorRing?360:(float)Math.Min(s.SweepAngle,360);var bounds=Bounds(cx,cy,inner,outer,start,sweep);int top=Math.Max(0,(int)(bounds.Top+.5f)),bottom=Math.Min(height,(int)(bounds.Bottom+.5f)),left=Math.Max(0,(int)(bounds.Left+.5f)),right=Math.Min(width,(int)(bounds.Right+.5f)),destination=top;if(left>width||top>height)return;var endpoints=new[]{Point(cx,cy,inner,start/180.0*Math.PI),Point(cx,cy,outer,start/180.0*Math.PI),Point(cx,cy,inner,(start+sweep)/180.0*Math.PI),Point(cx,cy,outer,(start+sweep)/180.0*Math.PI)};for(int row=top;row<bottom;row++){token.ThrowIfCancellationRequested();float dy=Math.Abs(cy-row);if(outer<=dy)continue;float dx=(float)Math.Sqrt(outer*outer-dy*dy);var intersections=new List<(float X,float Y)>{(-dx,row-cy),(dx,row-cy)};if(inner>dy){float ix=(float)Math.Sqrt(inner*inner-dy*dy);intersections.Add((-ix,row-cy));intersections.Add((ix,row-cy));}var hits=new List<int>(6);foreach(var p in intersections)if(Angle(p.X,p.Y,start,sweep))hits.Add((int)(cx+p.X+.5f));for(int k=0;k<4;k+=2){var a=endpoints[k];var b=endpoints[k+1];if(a.Y<row&&b.Y>=row||b.Y<row&&a.Y>=row)hits.Add((int)(a.X+(row-a.Y)/(b.Y-a.Y)*(b.X-a.X)+.5f));}hits.Sort();for(int i=0;i+1<hits.Count&&hits[i]<right;i+=2)if(hits[i+1]>left)Span(image,width,height,destination,Math.Max(left,hits[i]),Math.Min(right,hits[i+1]),value,ref valid);destination++;}}
}
